// Backup checks are bounded to this new game's settings and measured history.
export function validateForestSettings(settings){const s=settings?.limitBreak;if(!s)return;if(typeof s!=='object'||Array.isArray(s)||!['auto','low','medium','high','ultra','maximum'].includes(s.preset)||!Array.isArray(s.history)||s.history.length>20)throw Error('Project Limit Break settings are invalid.');for(const r of s.history){if(r?.version!==1||typeof r.id!=='string'||r.id.length>80||!Number.isFinite(r.at)||!r.settings||typeof r.settings.label!=='string'||r.settings.label.length>80||!r.metadata||typeof r.metadata.renderer!=='string'||r.metadata.renderer.length>80||!['renderWidth','renderHeight'].every(k=>Number.isFinite(r.metadata[k])&&r.metadata[k]>0&&r.metadata[k]<=32768)||!Array.isArray(r.stages)||r.stages.length<1||r.stages.length>8||!Array.isArray(r.frameTimesMs)||r.frameTimesMs.length>36000||!r.frameTimesMs.every(n=>Number.isFinite(n)&&n>0))throw Error('A forest benchmark result is invalid.');for(const report of [r.overall,...r.stages]){if(!report||!Number.isInteger(report.frames)||report.frames<1||!['averageFPS','onePercentLowFPS','medianMs','p95Ms','worstMs'].every(k=>Number.isFinite(report[k])&&report[k]>=0))throw Error('Forest benchmark measurements are invalid.');}if(r.frameTimesMs.length!==r.overall.frames)throw Error('Forest benchmark frame data is incomplete.');}}
